  1→// Package settings provides configuration loading for Entire.
  2→// This package is separate from cli to allow strategy package to import it
  3→// without creating an import cycle (cli imports strategy).
  4→package settings
  5→
  6→import (
  7→	"bytes"
  8→	"encoding/json"
  9→	"fmt"
 10→	"io"
 11→	"os"
 12→	"path/filepath"
 13→
 14→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 15→	"github.com/entireio/cli/cmd/entire/cli/paths"
 16→)
 17→
 18→const (
 19→	// EntireSettingsFile is the path to the Entire settings file
 20→	EntireSettingsFile = ".entire/settings.json"
 21→	// EntireSettingsLocalFile is the path to the local settings override file (not committed)
 22→	EntireSettingsLocalFile = ".entire/settings.local.json"
 23→)
 24→
 25→// EntireSettings represents the .entire/settings.json configuration
 26→type EntireSettings struct {
 27→
 28→	// Enabled indicates whether Entire is active. When false, CLI commands
 29→	// show a disabled message and hooks exit silently. Defaults to true.
 30→	Enabled bool `json:"enabled"`
 31→
 32→	// LocalDev indicates whether to use "go run" instead of the "entire" binary
 33→	// This is used for development when the binary is not installed
 34→	LocalDev bool `json:"local_dev,omitempty"`
 35→
 36→	// LogLevel sets the logging verbosity (debug, info, warn, error).
 37→	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
 38→	// Defaults to "info".
 39→	LogLevel string `json:"log_level,omitempty"`
 40→
 41→	// StrategyOptions contains strategy-specific configuration
 42→	StrategyOptions map[string]any `json:"strategy_options,omitempty"`
 43→
 44→	// Telemetry controls anonymous usage analytics.
 45→	// nil = not asked yet (show prompt), true = opted in, false = opted out
 46→	Telemetry *bool `json:"telemetry,omitempty"`
 47→
 48→	// Deprecated: no longer used. Exists to tolerate old settings files
 49→	// that still contain "strategy": "auto-commit" or similar.
 50→	Strategy string `json:"strategy,omitempty"`
 51→}
 52→
 53→// Load loads the Entire settings from .entire/settings.json,
 54→// then applies any overrides from .entire/settings.local.json if it exists.
 55→// Returns default settings if neither file exists.
 56→// Works correctly from any subdirectory within the repository.
 57→func Load() (*EntireSettings, error) {
 58→	// Get absolute paths for settings files
 59→	settingsFileAbs, err := paths.AbsPath(EntireSettingsFile)
 60→	if err != nil {
 61→		settingsFileAbs = EntireSettingsFile // Fallback to relative
 62→	}
 63→	localSettingsFileAbs, err := paths.AbsPath(EntireSettingsLocalFile)
 64→	if err != nil {
 65→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
 66→	}
 67→
 68→	// Load base settings
 69→	settings, err := loadFromFile(settingsFileAbs)
 70→	if err != nil {
 71→		return nil, fmt.Errorf("reading settings file: %w", err)
 72→	}
 73→
 74→	// Apply local overrides if they exist
 75→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
 76→	if err != nil {
 77→		if !os.IsNotExist(err) {
 78→			return nil, fmt.Errorf("reading local settings file: %w", err)
 79→		}
 80→		// Local file doesn't exist, continue without overrides
 81→	} else {
 82→		if err := mergeJSON(settings, localData); err != nil {
 83→			return nil, fmt.Errorf("merging local settings: %w", err)
 84→		}
 85→	}
 86→
 87→	return settings, nil
 88→}
 89→
 90→// LoadFromFile loads settings from a specific file path without merging local overrides.
 91→// Returns default settings if the file doesn't exist.
 92→// Use this when you need to display individual settings files separately.
 93→func LoadFromFile(filePath string) (*EntireSettings, error) {
 94→	return loadFromFile(filePath)
 95→}
 96→
 97→// loadFromFile loads settings from a specific file path.
 98→// Returns default settings if the file doesn't exist.
 99→func loadFromFile(filePath string) (*EntireSettings, error) {
100→	settings := &EntireSettings{
101→		Enabled: true, // Default to enabled
102→	}
103→
104→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
105→	if err != nil {
106→		if os.IsNotExist(err) {
107→			return settings, nil
108→		}
109→		return nil, fmt.Errorf("%w", err)
110→	}
111→
112→	dec := json.NewDecoder(bytes.NewReader(data))
113→	dec.DisallowUnknownFields()
114→	if err := dec.Decode(settings); err != nil {
115→		return nil, fmt.Errorf("parsing settings file: %w", err)
116→	}
117→
118→	return settings, nil
119→}
120→
121→// mergeJSON merges JSON data into existing settings.
122→// Only non-zero values from the JSON override existing settings.
123→func mergeJSON(settings *EntireSettings, data []byte) error {
124→	// First, validate that there are no unknown keys using strict decoding
125→	dec := json.NewDecoder(bytes.NewReader(data))
126→	dec.DisallowUnknownFields()
127→	var temp EntireSettings
128→	if err := dec.Decode(&temp); err != nil {
129→		return fmt.Errorf("parsing JSON: %w", err)
130→	}
131→
132→	// Parse into a map to check which fields are present
133→	var raw map[string]json.RawMessage
134→	if err := json.Unmarshal(data, &raw); err != nil {
135→		return fmt.Errorf("parsing JSON: %w", err)
136→	}
137→
138→	// Override enabled if present
139→	if enabledRaw, ok := raw["enabled"]; ok {
140→		var e bool
141→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
142→			return fmt.Errorf("parsing enabled field: %w", err)
143→		}
144→		settings.Enabled = e
145→	}
146→
147→	// Override local_dev if present
148→	if localDevRaw, ok := raw["local_dev"]; ok {
149→		var ld bool
150→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
151→			return fmt.Errorf("parsing local_dev field: %w", err)
152→		}
153→		settings.LocalDev = ld
154→	}
155→
156→	// Override log_level if present and non-empty
157→	if logLevelRaw, ok := raw["log_level"]; ok {
158→		var ll string
159→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
160→			return fmt.Errorf("parsing log_level field: %w", err)
161→		}
162→		if ll != "" {
163→			settings.LogLevel = ll
164→		}
165→	}
166→
167→	// Merge strategy_options if present
168→	if optionsRaw, ok := raw["strategy_options"]; ok {
169→		var opts map[string]any
170→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
171→			return fmt.Errorf("parsing strategy_options field: %w", err)
172→		}
173→		if settings.StrategyOptions == nil {
174→			settings.StrategyOptions = opts
175→		} else {
176→			for k, v := range opts {
177→				settings.StrategyOptions[k] = v
178→			}
179→		}
180→	}
181→
182→	// Override telemetry if present
183→	if telemetryRaw, ok := raw["telemetry"]; ok {
184→		var t bool
185→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
186→			return fmt.Errorf("parsing telemetry field: %w", err)
187→		}
188→		settings.Telemetry = &t
189→	}
190→
191→	return nil
192→}
193→
194→// IsSetUp returns true if Entire has been set up in the current repository.
195→// This checks if .entire/settings.json exists.
196→// Use this to avoid creating files/directories in repos where Entire was never enabled.
197→func IsSetUp() bool {
198→	settingsFileAbs, err := paths.AbsPath(EntireSettingsFile)
199→	if err != nil {
200→		return false
201→	}
202→	_, err = os.Stat(settingsFileAbs)
203→	return err == nil
204→}
205→
206→// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
207→// This checks if .entire/settings.json exists AND has enabled: true.
208→// Use this for hooks that should be no-ops when Entire is not active.
209→func IsSetUpAndEnabled() bool {
210→	if !IsSetUp() {
211→		return false
212→	}
213→	s, err := Load()
214→	if err != nil {
215→		return false
216→	}
217→	return s.Enabled
218→}
219→
220→// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
221→// Returns false by default if settings cannot be loaded or the key is missing.
222→func IsSummarizeEnabled() bool {
223→	settings, err := Load()
224→	if err != nil {
225→		return false
226→	}
227→	return settings.IsSummarizeEnabled()
228→}
229→
230→// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
231→func (s *EntireSettings) IsSummarizeEnabled() bool {
232→	if s.StrategyOptions == nil {
233→		return false
234→	}
235→	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
236→	if !ok {
237→		return false
238→	}
239→	enabled, ok := summarizeOpts["enabled"].(bool)
240→	if !ok {
241→		return false
242→	}
243→	return enabled
244→}
245→
246→// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
247→// Returns true if push_sessions is explicitly set to false.
248→func (s *EntireSettings) IsPushSessionsDisabled() bool {
249→	if s.StrategyOptions == nil {
250→		return false
251→	}
252→	val, exists := s.StrategyOptions["push_sessions"]
253→	if !exists {
254→		return false
255→	}
256→	if boolVal, ok := val.(bool); ok {
257→		return !boolVal // disabled = !push_sessions
258→	}
259→	return false
260→}
261→
262→// FilesWithDeprecatedStrategy returns the relative paths of settings files
263→// that still contain the deprecated "strategy" field.
264→func FilesWithDeprecatedStrategy() []string {
265→	var files []string
266→	for _, rel := range []string{EntireSettingsFile, EntireSettingsLocalFile} {
267→		abs, err := paths.AbsPath(rel)
268→		if err != nil {
269→			abs = rel // Fallback to relative
270→		}
271→		s, err := LoadFromFile(abs)
272→		if err != nil || s.Strategy == "" {
273→			continue
274→		}
275→		files = append(files, rel)
276→	}
277→	return files
278→}
279→
280→// WriteDeprecatedStrategyWarnings writes user-friendly deprecation warnings
281→// for each settings file that still contains the "strategy" field.
282→// Returns true if any warnings were written.
283→func WriteDeprecatedStrategyWarnings(w io.Writer) bool {
284→	files := FilesWithDeprecatedStrategy()
285→	for _, f := range files {
286→		fmt.Fprintf(w, "Note: \"%s\" in %s is no longer needed and can be removed. 'manual-commit' is now the only supported strategy.\n", "strategy", f)
287→	}
288→	return len(files) > 0
289→}
290→
291→// Save saves the settings to .entire/settings.json.
292→func Save(settings *EntireSettings) error {
293→	return saveToFile(settings, EntireSettingsFile)
294→}
295→
296→// SaveLocal saves the settings to .entire/settings.local.json.
297→func SaveLocal(settings *EntireSettings) error {
298→	return saveToFile(settings, EntireSettingsLocalFile)
299→}
300→
301→// saveToFile saves settings to the specified file path.
302→func saveToFile(settings *EntireSettings, filePath string) error {
303→	// Get absolute path for the file
304→	filePathAbs, err := paths.AbsPath(filePath)
305→	if err != nil {
306→		filePathAbs = filePath // Fallback to relative
307→	}
308→
309→	// Ensure directory exists
310→	dir := filepath.Dir(filePathAbs)
311→	if err := os.MkdirAll(dir, 0o750); err != nil {
312→		return fmt.Errorf("creating settings directory: %w", err)
313→	}
314→
315→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
316→	if err != nil {
317→		return fmt.Errorf("marshaling settings: %w", err)
318→	}
319→
320→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
321→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
322→		return fmt.Errorf("writing settings file: %w", err)
323→	}
324→	return nil
325→}
