  1→package strategy
  2→
  3→import (
  4→	"context"
  5→	"errors"
  6→	"fmt"
  7→	"os"
  8→	"os/exec"
  9→	"path/filepath"
 10→	"strings"
 11→	"sync"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/settings"
 14→)
 15→
 16→// Hook marker used to identify Entire CLI hooks
 17→const entireHookMarker = "Entire CLI hooks"
 18→
 19→const backupSuffix = ".pre-entire"
 20→const chainComment = "# Chain: run pre-existing hook"
 21→
 22→// gitHookNames are the git hooks managed by Entire CLI
 23→var gitHookNames = []string{"prepare-commit-msg", "commit-msg", "post-commit", "pre-push"}
 24→
 25→// ManagedGitHookNames returns the list of git hooks managed by Entire CLI.
 26→// This is useful for tests that need to manipulate hooks.
 27→func ManagedGitHookNames() []string {
 28→	return gitHookNames
 29→}
 30→
 31→// hookSpec defines a git hook's name and content template (without chain call).
 32→type hookSpec struct {
 33→	name    string
 34→	content string
 35→}
 36→
 37→// GetGitDir returns the actual git directory path by delegating to git itself.
 38→// This handles both regular repositories and worktrees, and inherits git's
 39→// security validation for gitdir references.
 40→func GetGitDir() (string, error) {
 41→	return getGitDirInPath(".")
 42→}
 43→
 44→// hooksDirCache caches the hooks directory to avoid repeated git subprocess spawns.
 45→// Keyed by current working directory to handle directory changes.
 46→var (
 47→	hooksDirMu       sync.RWMutex
 48→	hooksDirCache    string
 49→	hooksDirCacheDir string
 50→)
 51→
 52→// GetHooksDir returns the active hooks directory path.
 53→// This respects core.hooksPath and correctly resolves to the common hooks
 54→// directory when called from a linked worktree.
 55→// The result is cached per working directory.
 56→func GetHooksDir() (string, error) {
 57→	cwd, err := os.Getwd() //nolint:forbidigo // cache key for hooks dir, same pattern as paths.WorktreeRoot()
 58→	if err != nil {
 59→		cwd = ""
 60→	}
 61→
 62→	hooksDirMu.RLock()
 63→	if hooksDirCache != "" && hooksDirCacheDir == cwd {
 64→		cached := hooksDirCache
 65→		hooksDirMu.RUnlock()
 66→		return cached, nil
 67→	}
 68→	hooksDirMu.RUnlock()
 69→
 70→	result, err := getHooksDirInPath(".")
 71→	if err != nil {
 72→		return "", err
 73→	}
 74→
 75→	hooksDirMu.Lock()
 76→	hooksDirCache = result
 77→	hooksDirCacheDir = cwd
 78→	hooksDirMu.Unlock()
 79→
 80→	return result, nil
 81→}
 82→
 83→// ClearHooksDirCache clears the cached hooks directory.
 84→// This is primarily useful for testing when changing directories.
 85→func ClearHooksDirCache() {
 86→	hooksDirMu.Lock()
 87→	hooksDirCache = ""
 88→	hooksDirCacheDir = ""
 89→	hooksDirMu.Unlock()
 90→}
 91→
 92→// getGitDirInPath returns the git directory for a repository at the given path.
 93→// It delegates to `git rev-parse --git-dir` to leverage git's own validation.
 94→func getGitDirInPath(dir string) (string, error) {
 95→	ctx := context.Background()
 96→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-dir")
 97→	cmd.Dir = dir
 98→	output, err := cmd.Output()
 99→	if err != nil {
100→		return "", errors.New("not a git repository")
101→	}
102→
103→	gitDir := strings.TrimSpace(string(output))
104→
105→	// git rev-parse --git-dir returns relative paths from the working directory,
106→	// so we need to make it absolute if it isn't already
107→	if !filepath.IsAbs(gitDir) {
108→		gitDir = filepath.Join(dir, gitDir)
109→	}
110→
111→	return filepath.Clean(gitDir), nil
112→}
113→
114→// getHooksDirInPath returns the active hooks directory for a repository at the given path.
115→// It delegates to `git rev-parse --git-path hooks` so Git resolves:
116→// - linked-worktree common hooks directory
117→// - core.hooksPath (relative or absolute)
118→func getHooksDirInPath(dir string) (string, error) {
119→	ctx := context.Background()
120→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-path", "hooks")
121→	cmd.Dir = dir
122→	output, err := cmd.Output()
123→	if err != nil {
124→		return "", errors.New("not a git repository")
125→	}
126→
127→	hooksDir := strings.TrimSpace(string(output))
128→	if !filepath.IsAbs(hooksDir) {
129→		hooksDir = filepath.Join(dir, hooksDir)
130→	}
131→
132→	return filepath.Clean(hooksDir), nil
133→}
134→
135→// IsGitHookInstalled checks if all generic Entire CLI hooks are installed.
136→func IsGitHookInstalled() bool {
137→	hooksDir, err := GetHooksDir()
138→	if err != nil {
139→		return false
140→	}
141→	return isGitHookInstalledInHooksDir(hooksDir)
142→}
143→
144→// IsGitHookInstalledInDir checks if all Entire CLI hooks are installed in the given repo directory.
145→// This is useful for tests that need to check hooks without changing the working directory.
146→func IsGitHookInstalledInDir(repoDir string) bool {
147→	hooksDir, err := getHooksDirInPath(repoDir)
148→	if err != nil {
149→		return false
150→	}
151→	return isGitHookInstalledInHooksDir(hooksDir)
152→}
153→
154→// isGitHookInstalledInHooksDir checks if all hooks are installed in the given hooks directory.
155→func isGitHookInstalledInHooksDir(hooksDir string) bool {
156→	for _, hook := range gitHookNames {
157→		hookPath := filepath.Join(hooksDir, hook)
158→		data, err := os.ReadFile(hookPath) //nolint:gosec // Path is constructed from constants
159→		if err != nil {
160→			return false
161→		}
162→		if !strings.Contains(string(data), entireHookMarker) {
163→			return false
164→		}
165→	}
166→	return true
167→}
168→
169→// buildHookSpecs returns the hook specifications for all managed hooks.
170→func buildHookSpecs(cmdPrefix string) []hookSpec {
171→	return []hookSpec{
172→		{
173→			name: "prepare-commit-msg",
174→			content: fmt.Sprintf(`#!/bin/sh
175→# %s
176→%s hooks git prepare-commit-msg "$1" "$2" 2>/dev/null || true
177→`, entireHookMarker, cmdPrefix),
178→		},
179→		{
180→			name: "commit-msg",
181→			content: fmt.Sprintf(`#!/bin/sh
182→# %s
183→# Commit-msg hook: strip trailer if no user content (allows aborting empty commits)
184→%s hooks git commit-msg "$1" || exit 1
185→`, entireHookMarker, cmdPrefix),
186→		},
187→		{
188→			name: "post-commit",
189→			content: fmt.Sprintf(`#!/bin/sh
190→# %s
191→# Post-commit hook: condense session data if commit has Entire-Checkpoint trailer
192→%s hooks git post-commit 2>/dev/null || true
193→`, entireHookMarker, cmdPrefix),
194→		},
195→		{
196→			name: "pre-push",
197→			content: fmt.Sprintf(`#!/bin/sh
198→# %s
199→# Pre-push hook: push session logs alongside user's push
200→# $1 is the remote name (e.g., "origin")
201→%s hooks git pre-push "$1" || true
202→`, entireHookMarker, cmdPrefix),
203→		},
204→	}
205→}
206→
207→// InstallGitHook installs generic git hooks that delegate to `entire hook` commands.
208→// These hooks work with any strategy - the strategy is determined at runtime.
209→// If silent is true, no output is printed (except backup notifications, which always print).
210→// localDev controls whether hooks use "go run" (true) or the "entire" binary (false).
211→// Returns the number of hooks that were installed (0 if all already up to date).
212→func InstallGitHook(silent bool, localDev bool) (int, error) {
213→	hooksDir, err := GetHooksDir()
214→	if err != nil {
215→		return 0, err
216→	}
217→
218→	if err := os.MkdirAll(hooksDir, 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
219→		return 0, fmt.Errorf("failed to create hooks directory: %w", err)
220→	}
221→
222→	specs := buildHookSpecs(hookCmdPrefix(localDev))
223→	installedCount := 0
224→
225→	for _, spec := range specs {
226→		hookPath := filepath.Join(hooksDir, spec.name)
227→		backupPath := hookPath + backupSuffix
228→		backupExists := fileExists(backupPath)
229→
230→		// Back up existing non-Entire hooks
231→		existing, existingErr := os.ReadFile(hookPath) //nolint:gosec // path is controlled
232→		if existingErr == nil && !strings.Contains(string(existing), entireHookMarker) {
233→			if !backupExists {
234→				if err := os.Rename(hookPath, backupPath); err != nil {
235→					return installedCount, fmt.Errorf("failed to back up %s: %w", spec.name, err)
236→				}
237→				fmt.Fprintf(os.Stderr, "[entire] Backed up existing %s to %s%s\n", spec.name, spec.name, backupSuffix)
238→			} else {
239→				fmt.Fprintf(os.Stderr, "[entire] Warning: replacing %s (backup %s%s already exists from a previous install)\n", spec.name, spec.name, backupSuffix)
240→			}
241→			backupExists = true
242→		}
243→
244→		// Chain to backup if one exists
245→		content := spec.content
246→		if backupExists {
247→			content = generateChainedContent(spec.content, spec.name)
248→		}
249→
250→		written, err := writeHookFile(hookPath, content)
251→		if err != nil {
252→			return installedCount, fmt.Errorf("failed to install %s hook: %w", spec.name, err)
253→		}
254→		if written {
255→			installedCount++
256→		}
257→	}
258→
259→	if !silent {
260→		fmt.Println("✓ Installed git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
261→		fmt.Println("  Hooks delegate to the current strategy at runtime")
262→	}
263→
264→	return installedCount, nil
265→}
266→
267→// writeHookFile writes a hook file if it doesn't exist or has different content.
268→// Returns true if the file was written, false if it already had the same content.
269→func writeHookFile(path, content string) (bool, error) {
270→	// Check if file already exists with same content
271→	existing, err := os.ReadFile(path) //nolint:gosec // path is controlled
272→	if err == nil && string(existing) == content {
273→		return false, nil // Already up to date
274→	}
275→
276→	// Git hooks must be executable (0o755)
277→	if err := os.WriteFile(path, []byte(content), 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
278→		return false, fmt.Errorf("failed to write hook file %s: %w", path, err)
279→	}
280→	return true, nil
281→}
282→
283→// RemoveGitHook removes all Entire CLI git hooks from the repository.
284→// If a .pre-entire backup exists, it is restored.
285→// Returns the number of hooks removed.
286→func RemoveGitHook() (int, error) {
287→	hooksDir, err := GetHooksDir()
288→	if err != nil {
289→		return 0, err
290→	}
291→
292→	removed := 0
293→	var removeErrors []string
294→
295→	for _, hook := range gitHookNames {
296→		hookPath := filepath.Join(hooksDir, hook)
297→		backupPath := hookPath + backupSuffix
298→
299→		// Remove the hook if it contains our marker
300→		data, err := os.ReadFile(hookPath) //nolint:gosec // path is controlled
301→		hookIsOurs := err == nil && strings.Contains(string(data), entireHookMarker)
302→		hookExists := err == nil
303→
304→		if hookIsOurs {
305→			if err := os.Remove(hookPath); err != nil {
306→				removeErrors = append(removeErrors, fmt.Sprintf("%s: %v", hook, err))
307→				continue
308→			}
309→			removed++
310→		}
311→
312→		// Restore .pre-entire backup if it exists
313→		if fileExists(backupPath) {
314→			if hookExists && !hookIsOurs {
315→				// A non-Entire hook is present — don't overwrite it with the backup
316→				fmt.Fprintf(os.Stderr, "[entire] Warning: %s was modified since install; backup %s%s left in place\n", hook, hook, backupSuffix)
317→			} else {
318→				if err := os.Rename(backupPath, hookPath); err != nil {
319→					removeErrors = append(removeErrors, fmt.Sprintf("restore %s%s: %v", hook, backupSuffix, err))
320→				}
321→			}
322→		}
323→	}
324→
325→	if len(removeErrors) > 0 {
326→		return removed, fmt.Errorf("failed to remove hooks: %s", strings.Join(removeErrors, "; "))
327→	}
328→	return removed, nil
329→}
330→
331→// generateChainedContent appends a chain call to the base hook content,
332→// so the pre-existing hook (backed up to .pre-entire) is called after our hook.
333→func generateChainedContent(baseContent, hookName string) string {
334→	return baseContent + fmt.Sprintf(`%s
335→_entire_hook_dir="$(dirname "$0")"
336→if [ -x "$_entire_hook_dir/%s%s" ]; then
337→    "$_entire_hook_dir/%s%s" "$@"
338→fi
339→`, chainComment, hookName, backupSuffix, hookName, backupSuffix)
340→}
