342→// hookCmdPrefix returns the command prefix for hook scripts and warning messages.
343→// Returns "go run ./cmd/entire/main.go" when local_dev is enabled, "entire" otherwise.
344→func hookCmdPrefix(localDev bool) string {
345→	if localDev {
346→		return "go run ./cmd/entire/main.go"
347→	}
348→	return "entire"
349→}
