 266→func runDisable(w io.Writer, useProjectSettings bool) error {
 267→	settings, err := LoadEntireSettings()
 268→	if err != nil {
 269→		return fmt.Errorf("failed to load settings: %w", err)
 270→	}
 271→
 272→	settings.Enabled = false
 273→
 274→	// If --project flag is specified, always write to project settings
 275→	if useProjectSettings {
 276→		if err := SaveEntireSettings(settings); err != nil {
 277→			return fmt.Errorf("failed to save settings: %w", err)
 278→		}
 279→	} else {
