 281→		if err := SaveEntireSettingsLocal(settings); err != nil {
 282→			return fmt.Errorf("failed to save local settings: %w", err)
 283→		}
 284→	}
 285→
 286→	fmt.Fprintln(w, "Entire is now disabled.")
 287→	return nil
