 564→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
 565→// If strategyName is provided, it sets the strategy; otherwise uses default.
 566→func setupAgentHooksNonInteractive(w io.Writer, ag agent.Agent, localDev, forceHooks, skipPushSessions, telemetry bool) error {
 567→	agentName := ag.Name()
 568→	// Check if agent supports hooks
 569→	hookAgent, ok := ag.(agent.HookSupport)
 570→	if !ok {
 571→		return fmt.Errorf("agent %s does not support hooks", agentName)
 572→	}
 573→
 574→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
 575→
 576→	// Install agent hooks (agent hooks don't depend on settings)
 577→	installedHooks, err := hookAgent.InstallHooks(localDev, forceHooks)
 578→	if err != nil {
 579→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
 580→	}
 581→
 582→	// Setup .entire directory
 583→	if _, err := setupEntireDirectory(); err != nil {
 584→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 585→	}
 586→
 587→	// Load existing settings to preserve other options (like strategy_options.push)
 588→	settings, err := LoadEntireSettings()
 589→	if err != nil {
 590→		// If we can't load, start with defaults
 591→		settings = &EntireSettings{}
 592→	}
 593→	settings.Enabled = true
 594→	if localDev {
 595→		settings.LocalDev = localDev
 596→	}
 597→
 598→	// Set push_sessions option if --skip-push-sessions flag was provided
 599→	if skipPushSessions {
 600→		if settings.StrategyOptions == nil {
 601→			settings.StrategyOptions = make(map[string]interface{})
 602→		}
 603→		settings.StrategyOptions["push_sessions"] = false
 604→	}
 605→
 606→	// Handle telemetry for non-interactive mode
 607→	// Note: if telemetry is nil (not configured), it defaults to disabled
 608→	if !telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
 609→		f := false
 610→		settings.Telemetry = &f
 611→	}
 612→
 613→	if err := SaveEntireSettings(settings); err != nil {
 614→		return fmt.Errorf("failed to save settings: %w", err)
 615→	}
 616→
 617→	if _, err := strategy.InstallGitHook(true, localDev); err != nil {
 618→		return fmt.Errorf("failed to install git hooks: %w", err)
 619→	}
 620→	strategy.CheckAndWarnHookManagers(w, localDev)
 621→
 622→	if installedHooks == 0 {
 623→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
 624→		if ag.IsPreview() {
 625→			msg += " (Preview)"
 626→		}
 627→		fmt.Fprintf(w, "%s\n", msg)
 628→	} else {
 629→		msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
 630→		if ag.IsPreview() {
 631→			msg += " (Preview)"
 632→		}
 633→		fmt.Fprintf(w, "%s\n", msg)
 634→	}
 635→
 636→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
 637→
 638→	if err := strategy.EnsureSetup(); err != nil {
 639→		return fmt.Errorf("failed to setup strategy: %w", err)
 640→	}
 641→
 642→	fmt.Fprintln(w, "\nReady.")
 643→
 644→	return nil
 645→}
