 655→// determineSettingsTarget decides whether to write to settings.local.json based on:
 656→// - Whether settings.json already exists
 657→// - The --local and --project flags
 658→// Returns (useLocal, showNotification).
 659→func determineSettingsTarget(entireDir string, useLocal, useProject bool) (bool, bool) {
 660→	// Explicit --local flag always uses local settings
 661→	if useLocal {
 662→		return true, false
 663→	}
 664→
 665→	// Explicit --project flag always uses project settings
 666→	if useProject {
 667→		return false, false
 668→	}
 669→
 670→	// No flags specified - check if settings file exists
 671→	settingsPath := filepath.Join(entireDir, paths.SettingsFileName)
 672→	if _, err := os.Stat(settingsPath); err == nil {
 673→		// Settings file exists - auto-redirect to local with notification
 674→		return true, true
 675→	}
 676→
 677→	// Settings file doesn't exist - create it
 678→	return false, false
 679→}
