 750→// shellCompletionComment is the comment preceding the completion line
 751→const shellCompletionComment = "# Entire CLI shell completion"
 752→
 753→// errUnsupportedShell is returned when the user's shell is not supported for completion.
 754→var errUnsupportedShell = errors.New("unsupported shell")
 755→
 756→// shellCompletionTarget returns the rc file path and completion lines for the
 757→// user's current shell.
 758→func shellCompletionTarget() (shellName, rcFile, completionLine string, err error) {
 759→	home, err := os.UserHomeDir()
 760→	if err != nil {
 761→		return "", "", "", fmt.Errorf("cannot determine home directory: %w", err)
 762→	}
 763→
 764→	shell := os.Getenv("SHELL")
 765→	switch {
 766→	case strings.Contains(shell, "zsh"):
 767→		return "Zsh",
 768→			filepath.Join(home, ".zshrc"),
 769→			"autoload -Uz compinit && compinit && source <(entire completion zsh)",
 770→			nil
 771→	case strings.Contains(shell, "bash"):
 772→		bashRC := filepath.Join(home, ".bashrc")
 773→		if _, err := os.Stat(filepath.Join(home, ".bash_profile")); err == nil {
 774→			bashRC = filepath.Join(home, ".bash_profile")
 775→		}
 776→		return "Bash",
 777→			bashRC,
 778→			"source <(entire completion bash)",
 779→			nil
 780→	case strings.Contains(shell, "fish"):
 781→		return "Fish",
 782→			filepath.Join(home, ".config", "fish", "config.fish"),
 783→			"entire completion fish | source",
 784→			nil
 785→	default:
 786→		return "", "", "", errUnsupportedShell
 787→	}
 788→}
 789→
 790→// promptShellCompletion offers to add shell completion to the user's rc file.
 791→// Only prompts if completion is not already configured.
 792→func promptShellCompletion(w io.Writer) error {
 793→	shellName, rcFile, completionLine, err := shellCompletionTarget()
 794→	if err != nil {
 795→		if errors.Is(err, errUnsupportedShell) {
 796→			fmt.Fprintf(w, "Note: Shell completion not available for your shell. Supported: zsh, bash, fish.\n")
 797→			return nil
 798→		}
 799→		return fmt.Errorf("shell completion: %w", err)
 800→	}
 801→
 802→	if isCompletionConfigured(rcFile) {
 803→		fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
 804→		return nil
 805→	}
 806→
 807→	var selected string
 808→	form := NewAccessibleForm(
 809→		huh.NewGroup(
 810→			huh.NewSelect[string]().
 811→				Title(fmt.Sprintf("Enable shell completion? (detected: %s)", shellName)).
 812→				Options(
 813→					huh.NewOption("Yes", "yes"),
 814→					huh.NewOption("No", "no"),
 815→				).
 816→				Value(&selected),
 817→		),
 818→	)
 819→
 820→	if err := form.Run(); err != nil {
 821→		//nolint:nilerr // User cancelled - not a fatal error, just skip
 822→		return nil
 823→	}
 824→
 825→	if selected != "yes" {
 826→		return nil
 827→	}
 828→
 829→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
 830→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
 831→	}
 832→
 833→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
 834→	fmt.Fprintln(w, "  Restart your shell to activate")
 835→
 836→	return nil
 837→}
 838→
 839→// isCompletionConfigured checks if shell completion is already in the rc file.
 840→func isCompletionConfigured(rcFile string) bool {
 841→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
 842→	content, err := os.ReadFile(rcFile)
 843→	if err != nil {
 844→		return false // File doesn't exist or can't read, treat as not configured
 845→	}
 846→	return strings.Contains(string(content), "entire completion")
 847→}
 848→
 849→// appendShellCompletion adds the completion line to the rc file.
 850→func appendShellCompletion(rcFile, completionLine string) error {
 851→	if err := os.MkdirAll(filepath.Dir(rcFile), 0o700); err != nil {
 852→		return fmt.Errorf("creating directory: %w", err)
 853→	}
 854→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
 855→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
 856→	if err != nil {
 857→		return fmt.Errorf("opening file: %w", err)
 858→	}
 859→	defer f.Close()
 860→
 861→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
 862→	if err != nil {
 863→		return fmt.Errorf("writing completion: %w", err)
 864→	}
 865→	return nil
 866→}
