 911→// runUninstall completely removes Entire from the repository.
 912→func runUninstall(w, errW io.Writer, force bool) error {
 913→	// Check if we're in a git repository
 914→	if _, err := paths.WorktreeRoot(); err != nil {
 915→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
 916→		return NewSilentError(errors.New("not a git repository"))
 917→	}
 918→
 919→	// Gather counts for display
 920→	sessionStateCount := countSessionStates()
 921→	shadowBranchCount := countShadowBranches()
 922→	gitHooksInstalled := strategy.IsGitHookInstalled()
 923→	agentsWithInstalledHooks := GetAgentsWithHooksInstalled()
 924→	entireDirExists := checkEntireDirExists()
 925→
 926→	// Check if there's anything to uninstall
 927→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
 928→		shadowBranchCount == 0 && len(agentsWithInstalledHooks) == 0 {
 929→		fmt.Fprintln(w, "Entire is not installed in this repository.")
 930→		return nil
 931→	}
 932→
 933→	// Show confirmation prompt unless --force
 934→	if !force {
 935→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
 936→		if entireDirExists {
 937→			fmt.Fprintln(w, "  - .entire/ directory")
 938→		}
 939→		if gitHooksInstalled {
 940→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
 941→		}
 942→		if sessionStateCount > 0 {
 943→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
 944→		}
 945→		if shadowBranchCount > 0 {
 946→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
 947→		}
 948→		if len(agentsWithInstalledHooks) > 0 {
 949→			displayNames := make([]string, 0, len(agentsWithInstalledHooks))
 950→			for _, name := range agentsWithInstalledHooks {
 951→				if ag, err := agent.Get(name); err == nil {
 952→					displayNames = append(displayNames, string(ag.Type()))
 953→				}
 954→			}
 955→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(displayNames, ", "))
 956→		}
 957→		fmt.Fprintln(w)
 958→
 959→		var confirmed bool
 960→		form := NewAccessibleForm(
 961→			huh.NewGroup(
 962→				huh.NewConfirm().
 963→					Title("Are you sure you want to uninstall Entire?").
 964→					Affirmative("Yes, uninstall").
 965→					Negative("Cancel").
 966→					Value(&confirmed),
 967→			),
 968→		)
 969→
 970→		if err := form.Run(); err != nil {
 971→			return fmt.Errorf("confirmation cancelled: %w", err)
 972→		}
 973→
 974→		if !confirmed {
 975→			fmt.Fprintln(w, "Uninstall cancelled.")
 976→			return nil
 977→		}
 978→	}
 979→
 980→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
 981→
 982→	// 1. Remove agent hooks (lowest risk)
 983→	if err := removeAgentHooks(w); err != nil {
 984→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
 985→	}
 986→
 987→	// 2. Remove git hooks
 988→	removed, err := strategy.RemoveGitHook()
 989→	if err != nil {
 990→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
 991→	} else if removed > 0 {
 992→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
 993→	}
 994→
 995→	// 3. Remove session state files
 996→	statesRemoved, err := removeAllSessionStates()
 997→	if err != nil {
 998→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
 999→	} else if statesRemoved > 0 {
1000→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
1001→	}
1002→
1003→	// 4. Remove .entire/ directory
1004→	if err := removeEntireDirectory(); err != nil {
1005→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
1006→	} else if entireDirExists {
1007→		fmt.Fprintln(w, "  Removed .entire directory")
1008→	}
1009→
1010→	// 5. Remove shadow branches
1011→	branchesRemoved, err := removeAllShadowBranches()
1012→	if err != nil {
1013→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
1014→	} else if branchesRemoved > 0 {
1015→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
1016→	}
1017→
1018→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
1019→	return nil
1020→}
