1054→// removeAgentHooks removes hooks from all agents that support hooks.
1055→func removeAgentHooks(w io.Writer) error {
1056→	var errs []error
1057→	for _, name := range agent.List() {
1058→		ag, err := agent.Get(name)
1059→		if err != nil {
1060→			continue
1061→		}
1062→		hs, ok := ag.(agent.HookSupport)
1063→		if !ok {
1064→			continue
1065→		}
1066→		wasInstalled := hs.AreHooksInstalled()
1067→		if err := hs.UninstallHooks(); err != nil {
1068→			errs = append(errs, err)
1069→		} else if wasInstalled {
1070→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1071→		}
1072→	}
1073→	return errors.Join(errs...)
1074→}
