1076→// removeAllSessionStates removes all session state files and the directory.
1077→func removeAllSessionStates() (int, error) {
1078→	store, err := session.NewStateStore()
1079→	if err != nil {
1080→		return 0, fmt.Errorf("failed to create state store: %w", err)
1081→	}
1082→
1083→	// Count states before removing
1084→	states, err := store.List(context.Background())
1085→	if err != nil {
1086→		return 0, fmt.Errorf("failed to list session states: %w", err)
1087→	}
1088→	count := len(states)
1089→
1090→	// Remove the entire directory
1091→	if err := store.RemoveAll(); err != nil {
1092→		return 0, fmt.Errorf("failed to remove session states: %w", err)
1093→	}
1094→
1095→	return count, nil
1096→}
