1110→// removeAllShadowBranches removes all shadow branches.
1111→func removeAllShadowBranches() (int, error) {
1112→	branches, err := strategy.ListShadowBranches()
1113→	if err != nil {
1114→		return 0, fmt.Errorf("failed to list shadow branches: %w", err)
