  36→// errStop is a sentinel error used to break out of git log iteration.
  37→// Shared across strategies that iterate through git commits.
  38→// NOTE: A similar sentinel exists in checkpoint/temporary.go - this is intentional.
  39→// Each package needs its own package-scoped sentinel for git log iteration patterns.
  40→var errStop = errors.New("stop iteration")
