  42→// IsEmptyRepository returns true if the repository has no commits yet.
  43→// After git-init, HEAD points to an unborn branch (e.g., refs/heads/main)
  44→// whose target does not yet exist. repo.Head() returns ErrReferenceNotFound
  45→// in this case.
  46→func IsEmptyRepository(repo *git.Repository) bool {
  47→	_, err := repo.Head()
  48→	return errors.Is(err, plumbing.ErrReferenceNotFound)
  49→}
