  51→// EnsureSetup ensures the strategy is properly set up.
  52→func EnsureSetup() error {
  53→	if err := EnsureEntireGitignore(); err != nil {
  54→		return err
  55→	}
  56→
  57→	// Ensure the entire/checkpoints/v1 orphan branch exists for permanent session storage
  58→	repo, err := OpenRepository()
  59→	if err != nil {
  60→		return fmt.Errorf("failed to open git repository: %w", err)
  61→	}
  62→	if err := EnsureMetadataBranch(repo); err != nil {
  63→		return fmt.Errorf("failed to ensure metadata branch: %w", err)
  64→	}
  65→
  66→	// Install generic hooks (they delegate to strategy at runtime)
  67→	if !IsGitHookInstalled() {
  68→		if _, err := InstallGitHook(true, isLocalDev()); err != nil {
  69→			return fmt.Errorf("failed to install git hooks: %w", err)
  70→		}
  71→	}
  72→	return nil
  73→}
