  75→// IsAncestorOf checks if commit is an ancestor of (or equal to) target.
  76→// Returns true if target can reach commit by following parent links.
  77→// Limits search to 1000 commits to avoid excessive traversal.
  78→func IsAncestorOf(repo *git.Repository, commit, target plumbing.Hash) bool {
  79→	if commit == target {
  80→		return true
  81→	}
  82→
  83→	iter, err := repo.Log(&git.LogOptions{From: target})
  84→	if err != nil {
  85→		return false
  86→	}
  87→	defer iter.Close()
  88→
  89→	found := false
  90→	count := 0
  91→	_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
  92→		count++
  93→		if count > 1000 {
  94→			return errStop
  95→		}
  96→		if c.Hash == commit {
  97→			found = true
  98→			return errStop
  99→		}
 100→		return nil
 101→	})
 102→
 103→	return found
 104→}
