 106→// ListCheckpoints returns all checkpoints from the entire/checkpoints/v1 branch.
 107→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
 108→func ListCheckpoints() ([]CheckpointInfo, error) {
 109→	repo, err := OpenRepository()
 110→	if err != nil {
 111→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 112→	}
 113→
 114→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
 115→	ref, err := repo.Reference(refName, true)
 116→	if err != nil {
 117→		//nolint:nilerr // No sessions branch yet is expected, return empty list
 118→		return []CheckpointInfo{}, nil
 119→	}
 120→
 121→	commit, err := repo.CommitObject(ref.Hash())
 122→	if err != nil {
 123→		return nil, fmt.Errorf("failed to get commit object: %w", err)
 124→	}
 125→
 126→	tree, err := commit.Tree()
 127→	if err != nil {
 128→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
 129→	}
 130→
 131→	var checkpoints []CheckpointInfo
 132→
 133→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
 134→	// The tree has 2-character directories (hex buckets)
 135→	for _, bucketEntry := range tree.Entries {
 136→		if bucketEntry.Mode != filemode.Dir {
 137→			continue
 138→		}
 139→		// Bucket should be 2 hex chars
 140→		if len(bucketEntry.Name) != 2 {
 141→			continue
 142→		}
 143→
 144→		bucketTree, treeErr := repo.TreeObject(bucketEntry.Hash)
 145→		if treeErr != nil {
 146→			continue
 147→		}
 148→
 149→		// Each entry in the bucket is the remaining part of the checkpoint ID
 150→		for _, checkpointEntry := range bucketTree.Entries {
 151→			if checkpointEntry.Mode != filemode.Dir {
 152→				continue
 153→			}
 154→
 155→			checkpointTree, cpTreeErr := repo.TreeObject(checkpointEntry.Hash)
 156→			if cpTreeErr != nil {
 157→				continue
 158→			}
 159→
 160→			// Reconstruct checkpoint ID: <bucket><remaining>
 161→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
 162→			checkpointID, cpErr := id.NewCheckpointID(checkpointIDStr)
 163→			if cpErr != nil {
 164→				// Skip invalid checkpoint IDs
 165→				continue
 166→			}
 167→
 168→			info := CheckpointInfo{
 169→				CheckpointID: checkpointID,
 170→			}
 171→
 172→			// Get details from metadata file (CheckpointSummary format)
 173→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
 174→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
 175→					var summary checkpoint.CheckpointSummary
 176→					if json.Unmarshal([]byte(content), &summary) == nil && len(summary.Sessions) > 0 {
 177→						info.CheckpointsCount = summary.CheckpointsCount
 178→						info.FilesTouched = summary.FilesTouched
 179→						info.SessionCount = len(summary.Sessions)
 180→
 181→						// Read session-level metadata for Agent, SessionID, CreatedAt, SessionIDs
 182→						for i, sessionPaths := range summary.Sessions {
 183→							if sessionPaths.Metadata != "" {
 184→								// SessionFilePaths now contains absolute paths with leading "/"
 185→								// Strip the leading "/" for tree.File() which expects paths without leading slash
 186→								sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
 187→								if sessionFile, sErr := tree.File(sessionMetadataPath); sErr == nil {
 188→									if sessionContent, scErr := sessionFile.Contents(); scErr == nil {
 189→										var sessionMetadata checkpoint.CommittedMetadata
 190→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
 191→											info.SessionIDs = append(info.SessionIDs, sessionMetadata.SessionID)
 192→											// Use first session's metadata for Agent, SessionID, CreatedAt
 193→											if i == 0 {
 194→												info.Agent = sessionMetadata.Agent
 195→												info.SessionID = sessionMetadata.SessionID
 196→												info.CreatedAt = sessionMetadata.CreatedAt
 197→												info.IsTask = sessionMetadata.IsTask
 198→												info.ToolUseID = sessionMetadata.ToolUseID
 199→											}
 200→										}
 201→									}
 202→								}
 203→							}
 204→						}
 205→					}
 206→				}
 207→			}
 208→
 209→			checkpoints = append(checkpoints, info)
 210→		}
 211→	}
 212→
 213→	// Sort by time (most recent first)
 214→	sort.Slice(checkpoints, func(i, j int) bool {
 215→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
 216→	})
 217→
 218→	return checkpoints, nil
 219→}
