 231→// isProtectedPath returns true if relPath is inside a directory that should
 232→// never be modified or deleted during rewind or other destructive operations.
 233→// Protected directories include git internals, entire metadata, and all
 234→// registered agent config directories.
 235→func isProtectedPath(relPath string) bool {
 236→	for _, dir := range protectedDirs() {
 237→		if relPath == dir || strings.HasPrefix(relPath, dir+string(filepath.Separator)) {
 238→			return true
 239→		}
 240→	}
 241→	return false
 242→}
