 272→// resolveAgentType picks the best agent type from the context and existing state.
 273→// Priority: existing state (if specific) > context value > default fallback.
 274→func resolveAgentType(ctxAgentType agent.AgentType, state *SessionState) agent.AgentType {
 275→	if state != nil && isSpecificAgentType(state.AgentType) {
