 343→// readCheckpointMetadata reads metadata.json from a checkpoint path on entire/checkpoints/v1.
 344→// With the new format, root metadata.json is a CheckpointSummary with Agents array.
 345→// This function reads the summary and extracts relevant fields into CheckpointInfo,
 346→// also reading session-level metadata for IsTask/ToolUseID fields.
 347→func ReadCheckpointMetadata(tree *object.Tree, checkpointPath string) (*CheckpointInfo, error) {
 348→	metadataPath := checkpointPath + "/metadata.json"
 349→	file, err := tree.File(metadataPath)
 350→	if err != nil {
 351→		return nil, fmt.Errorf("failed to find metadata at %s: %w", metadataPath, err)
 352→	}
 353→
 354→	content, err := file.Contents()
 355→	if err != nil {
 356→		return nil, fmt.Errorf("failed to read metadata: %w", err)
 357→	}
 358→
 359→	// Try to parse as CheckpointSummary first (new format)
 360→	var summary checkpoint.CheckpointSummary
 361→	if err := json.Unmarshal([]byte(content), &summary); err == nil {
 362→		// If we have sessions array, this is the new format
 363→		if len(summary.Sessions) > 0 {
 364→			info := &CheckpointInfo{
 365→				CheckpointID:     summary.CheckpointID,
 366→				CheckpointsCount: summary.CheckpointsCount,
 367→				FilesTouched:     summary.FilesTouched,
 368→				SessionCount:     len(summary.Sessions),
 369→			}
 370→
 371→			// Read all sessions' metadata to populate SessionIDs and get other fields from first session
 372→			var sessionIDs []string
 373→			for i, sessionPaths := range summary.Sessions {
 374→				if sessionPaths.Metadata != "" {
 375→					// SessionFilePaths now contains absolute paths with leading "/"
 376→					// Strip the leading "/" for tree.File() which expects paths without leading slash
 377→					sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
 378→					if sessionFile, err := tree.File(sessionMetadataPath); err == nil {
 379→						if sessionContent, err := sessionFile.Contents(); err == nil {
 380→							var sessionMetadata checkpoint.CommittedMetadata
 381→							if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
 382→								sessionIDs = append(sessionIDs, sessionMetadata.SessionID)
 383→								// Use first session for Agent, SessionID, CreatedAt, IsTask, ToolUseID
 384→								if i == 0 {
 385→									info.Agent = sessionMetadata.Agent
 386→									info.SessionID = sessionMetadata.SessionID
 387→									info.CreatedAt = sessionMetadata.CreatedAt
 388→									info.IsTask = sessionMetadata.IsTask
 389→									info.ToolUseID = sessionMetadata.ToolUseID
 390→								}
 391→							}
 392→						}
 393→					}
 394→				}
 395→			}
 396→			info.SessionIDs = sessionIDs
 397→
 398→			return info, nil
 399→		}
 400→	}
 401→
 402→	// Fall back to parsing as CheckpointInfo (old format or direct info)
 403→	var metadata CheckpointInfo
 404→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
 405→		return nil, fmt.Errorf("failed to parse metadata: %w", err)
 406→	}
 407→
 408→	return &metadata, nil
 409→}
