 431→// ExtractFirstPrompt extracts and truncates the first meaningful prompt from prompt content.
 432→// Prompts are separated by "\n\n---\n\n". Skips empty prompts and separator-only content.
 433→// Returns empty string if no valid prompt is found.
 434→func ExtractFirstPrompt(content string) string {
 435→	if content == "" {
 436→		return ""
 437→	}
 438→
 439→	// Prompts are separated by "\n\n---\n\n"
 440→	// Find the first non-empty prompt
 441→	prompts := strings.Split(content, "\n\n---\n\n")
 442→	var firstPrompt string
 443→	for _, p := range prompts {
 444→		cleaned := strings.TrimSpace(p)
 445→		// Skip empty prompts or prompts that are just dashes/separators
 446→		if cleaned == "" || isOnlySeparators(cleaned) {
 447→			continue
 448→		}
 449→		firstPrompt = cleaned
 450→		break
 451→	}
 452→
 453→	if firstPrompt == "" {
 454→		return ""
 455→	}
 456→
 457→	return TruncateDescription(firstPrompt, MaxDescriptionLength)
 458→}
