 477→// ReadAgentTypeFromTree reads the agent type from a checkpoint's metadata.json file in a git tree.
 478→// If metadata.json doesn't exist (shadow branches), it falls back to detecting the agent
 479→// from the presence of agent-specific config files (.gemini/settings.json or .claude/).
 480→// Returns agent.AgentTypeUnknown if the agent type cannot be determined.
 481→func ReadAgentTypeFromTree(tree *object.Tree, checkpointPath string) agent.AgentType {
 482→	// First, try to read from metadata.json (present in condensed/committed checkpoints)
 483→	metadataPath := checkpointPath + "/" + paths.MetadataFileName
 484→	if file, err := tree.File(metadataPath); err == nil {
 485→		if content, err := file.Contents(); err == nil {
 486→			var metadata checkpoint.CommittedMetadata
 487→			if err := json.Unmarshal([]byte(content), &metadata); err == nil && metadata.Agent != "" {
 488→				return metadata.Agent
 489→			}
 490→		}
 491→	}
 492→
 493→	// Fall back to detecting agent from config files (shadow branches don't have metadata.json).
 494→	// Order: Gemini (most specific check), Claude (established default), OpenCode (newest/preview).
 495→	if _, err := tree.File(".gemini/settings.json"); err == nil {
 496→		return agent.AgentTypeGemini
 497→	}
 498→	if _, err := tree.Tree(".claude"); err == nil {
 499→		return agent.AgentTypeClaudeCode
 500→	}
 501→	// OpenCode: .opencode directory or opencode.json config
 502→	if _, err := tree.Tree(".opencode"); err == nil {
 503→		return agent.AgentTypeOpenCode
 504→	}
 505→	if _, err := tree.File("opencode.json"); err == nil {
 506→		return agent.AgentTypeOpenCode
 507→	}
 508→
 509→	return agent.AgentTypeUnknown
 510→}
