 512→// isOnlySeparators checks if a string contains only dashes, spaces, and newlines.
 513→func isOnlySeparators(s string) bool {
 514→	for _, r := range s {
 515→		if r != '-' && r != ' ' && r != '\n' && r != '\r' && r != '\t' {
 516→			return false
 517→		}
 518→	}
 519→	return true
 520→}
