 570→// OpenRepository opens the git repository with linked worktree support enabled.
 571→// It uses git.PlainOpenWithOptions with EnableDotGitCommonDir set to true,
 572→// which is required for proper operation in git worktrees created via 'git worktree add'.
 573→//
 574→// Without EnableDotGitCommonDir, go-git operations in worktrees can silently fail:
 575→// - Commits appear to succeed but are not persisted
 576→// - Refs are written to incorrect locations
 577→// - The worktree's HEAD/index don't get updated properly
 578→//
 579→// This happens because worktrees use .git as a file (pointing to the main repo)
 580→// rather than a directory, and go-git needs to route paths correctly between
 581→// shared (.git/) and per-worktree (.git/worktrees/<name>/) locations.
 582→//
 583→// The function first uses 'git rev-parse --show-toplevel' to find the repository
 584→// root, which works correctly even when called from a subdirectory within the repo.
 585→func OpenRepository() (*git.Repository, error) {
 586→	repoRoot, err := paths.WorktreeRoot()
 587→	if err != nil {
 588→		// Fallback to current directory if git command fails
 589→		// (e.g., if git is not installed or we're not in a repo)
 590→		repoRoot = "."
 591→	}
 592→
 593→	repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{
 594→		EnableDotGitCommonDir: true,
 595→	})
 596→	if err != nil {
 597→		return nil, fmt.Errorf("failed to open repository: %w", err)
 598→	}
 599→	return repo, nil
 600→}
 601→
 602→// IsInsideWorktree returns true if the current directory is inside a git worktree
 603→// (as opposed to the main repository). Worktrees have .git as a file pointing
 604→// to the main repo, while the main repo has .git as a directory.
 605→// This function works correctly from any subdirectory within the repository.
 606→func IsInsideWorktree() bool {
 607→	// First find the repository root
 608→	repoRoot, err := paths.WorktreeRoot()
 609→	if err != nil {
 610→		return false
 611→	}
 612→
 613→	gitPath := filepath.Join(repoRoot, gitDir)
 614→	gitInfo, err := os.Stat(gitPath)
 615→	if err != nil {
 616→		return false
 617→	}
 618→	return !gitInfo.IsDir()
 619→}
