 884→// countLines counts the number of lines in content.
 885→func countLines(content []byte) int {
 886→	if len(content) == 0 {
 887→		return 0
 888→	}
 889→	count := 1
 890→	for _, b := range content {
 891→		if b == '\n' {
 892→			count++
 893→		}
 894→	}
 895→	// Don't count trailing newline as extra line
 896→	if len(content) > 0 && content[len(content)-1] == '\n' {
 897→		count--
 898→	}
 899→	return count
 900→}
 901→
 902→// computeDiffStats computes added and removed line counts between old and new content.
 903→// Uses a simple line-based diff algorithm.
 904→func computeDiffStats(oldContent, newContent []byte) (added, removed int) {
 905→	oldLines := splitLines(oldContent)
 906→	newLines := splitLines(newContent)
 907→
 908→	// Build a set of old lines with counts
 909→	oldSet := make(map[string]int)
 910→	for _, line := range oldLines {
 911→		oldSet[line]++
 912→	}
 913→
 914→	// Check which new lines are truly new
 915→	for _, line := range newLines {
 916→		if oldSet[line] > 0 {
 917→			oldSet[line]--
 918→		} else {
 919→			added++
 920→		}
 921→	}
 922→
 923→	// Remaining old lines are removed
 924→	for _, count := range oldSet {
 925→		removed += count
 926→	}
 927→
 928→	return added, removed
 929→}
 930→
 931→// splitLines splits content into lines, preserving empty lines.
 932→func splitLines(content []byte) []string {
 933→	if len(content) == 0 {
 934→		return nil
 935→	}
 936→	s := string(content)
 937→	// Remove trailing newline to avoid empty last element
 938→	s = strings.TrimSuffix(s, "\n")
 939→	return strings.Split(s, "\n")
 940→}
