1109→// ErrBranchNotFound is returned by DeleteBranchCLI when the branch does not exist.
1110→var ErrBranchNotFound = errors.New("branch not found")
1111→
1112→// DeleteBranchCLI deletes a git branch using the git CLI.
1113→// Uses `git branch -D` instead of go-git's RemoveReference because go-git v5
1114→// doesn't properly persist deletions when refs are packed (.git/packed-refs)
1115→// or in a worktree context. This is the same class of go-git v5 bug that
1116→// affects checkout and reset --hard (see HardResetWithProtection).
1117→//
1118→// Returns ErrBranchNotFound if the branch does not exist, allowing callers
1119→// to use errors.Is for idempotent deletion patterns.
1120→func DeleteBranchCLI(branchName string) error {
1121→	ctx := context.Background()
1122→
1123→	// Pre-check: verify the branch exists so callers get a structured error
1124→	// instead of parsing git's output string (which varies across locales).
1125→	// git show-ref exits 1 for "not found" and 128+ for fatal errors (corrupt
1126→	// repo, permissions, not a git directory). Only map exit code 1 to
1127→	// ErrBranchNotFound; propagate other failures as-is.
1128→	check := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName) //nolint:gosec // branchName comes from internal shadow branch naming
1129→	if err := check.Run(); err != nil {
1130→		var exitErr *exec.ExitError
1131→		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1132→			return fmt.Errorf("%w: %s", ErrBranchNotFound, branchName)
1133→		}
1134→		return fmt.Errorf("failed to check branch %s: %w", branchName, err)
1135→	}
1136→
1137→	cmd := exec.CommandContext(ctx, "git", "branch", "-D", "--", branchName)
1138→	if output, err := cmd.CombinedOutput(); err != nil {
1139→		return fmt.Errorf("failed to delete branch %s: %s: %w", branchName, strings.TrimSpace(string(output)), err)
1140→	}
1141→	return nil
1142→}
1143→
1144→// branchExistsCLI checks if a branch exists using git CLI.
1145→// Returns nil if the branch exists, or an error if it does not.
1146→func branchExistsCLI(branchName string) error {
1147→	ctx := context.Background()
1148→	cmd := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName) //nolint:gosec // branchName comes from internal shadow branch naming
1149→	if err := cmd.Run(); err != nil {
1150→		return fmt.Errorf("branch %s not found: %w", branchName, err)
1151→	}
1152→	return nil
1153→}
