1155→// HardResetWithProtection performs a git reset --hard to the specified commit.
1156→// Uses the git CLI instead of go-git because go-git's HardReset incorrectly
1157→// deletes untracked directories (like .entire/) even when they're in .gitignore.
1158→// Returns the short commit ID (7 chars) on success for display purposes.
1159→func HardResetWithProtection(commitHash plumbing.Hash) (shortID string, err error) {
1160→	ctx := context.Background()
1161→	hashStr := commitHash.String()
1162→	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", hashStr) //nolint:gosec // hashStr is a plumbing.Hash, not user input
1163→	if output, err := cmd.CombinedOutput(); err != nil {
1164→		return "", fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
1165→	}
1166→
1167→	// Return short commit ID for display
1168→	shortID = hashStr
1169→	if len(shortID) > 7 {
1170→		shortID = shortID[:7]
1171→	}
1172→	return shortID, nil
1173→}
