1175→// collectUntrackedFiles collects untracked files in the working directory that are
1176→// NOT ignored by .gitignore. This is used to capture the initial state when starting
1177→// a session, ensuring untracked files present at session start are preserved during rewind.
1178→// Uses "git ls-files --others --exclude-standard -z" to respect .gitignore rules,
1179→// avoiding bloated session state from large ignored directories like node_modules/.
1180→// Returns paths relative to the repository root.
1181→func collectUntrackedFiles() ([]string, error) {
1182→	repoRoot, err := paths.WorktreeRoot()
1183→	if err != nil {
1184→		repoRoot = "."
1185→	}
1186→
1187→	cmd := exec.CommandContext(context.Background(), "git", "ls-files", "--others", "--exclude-standard", "-z")
1188→	cmd.Dir = repoRoot
1189→	output, err := cmd.Output()
1190→	if err != nil {
1191→		var exitErr *exec.ExitError
1192→		if errors.As(err, &exitErr) {
1193→			return nil, fmt.Errorf("git ls-files failed: %s: %w", strings.TrimSpace(string(exitErr.Stderr)), err)
1194→		}
1195→		return nil, fmt.Errorf("git ls-files failed: %w", err)
1196→	}
1197→
1198→	raw := string(output)
1199→	if raw == "" {
1200→		return nil, nil
1201→	}
1202→
1203→	var files []string
1204→	for _, f := range strings.Split(raw, "\x00") {
1205→		// Defense-in-depth: filter protected paths even though --exclude-standard should already handle them
1206→		if f != "" && !isProtectedPath(f) {
1207→			files = append(files, f)
1208→		}
1209→	}
1210→	return files, nil
1211→}
