1213→// ExtractSessionIDFromCommit extracts the session ID from a commit's trailers.
1214→// It checks the Entire-Session trailer first, then falls back to extracting from
1215→// the metadata directory path in the Entire-Metadata trailer.
1216→// Returns empty string if no session ID is found.
1217→func ExtractSessionIDFromCommit(commit *object.Commit) string {
1218→	// Try Entire-Session trailer first
1219→	if sessionID, found := trailers.ParseSession(commit.Message); found {
1220→		return sessionID
1221→	}
1222→
1223→	// Try extracting from metadata directory (last path component)
1224→	if metadataDir, found := trailers.ParseMetadata(commit.Message); found {
1225→		return filepath.Base(metadataDir)
1226→	}
1227→
1228→	return ""
1229→}
