1240→// createCommit creates a commit object
1241→func createCommit(repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) { //nolint:unparam // already present in codebase
1242→	now := time.Now()
1243→	sig := object.Signature{
1244→		Name:  authorName,
1245→		Email: authorEmail,
1246→		When:  now,
1247→	}
1248→
1249→	commit := &object.Commit{
1250→		TreeHash:  treeHash,
1251→		Author:    sig,
1252→		Committer: sig,
1253→		Message:   message,
1254→	}
1255→
1256→	// Add parent if not a new branch
1257→	if parentHash != plumbing.ZeroHash {
1258→		commit.ParentHashes = []plumbing.Hash{parentHash}
1259→	}
1260→
1261→	obj := repo.Storer.NewEncodedObject()
1262→	if err := commit.Encode(obj); err != nil {
1263→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
1264→	}
1265→
1266→	hash, err := repo.Storer.SetEncodedObject(obj)
1267→	if err != nil {
1268→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
1269→	}
1270→
1271→	return hash, nil
1272→}
