1360→// GetCurrentBranchName returns the short name of the current branch if HEAD points to a branch.
1361→// Returns an empty string if in detached HEAD state or if there's an error reading HEAD.
1362→// This is used to capture branch metadata for checkpoints.
1363→func GetCurrentBranchName(repo *git.Repository) string {
1364→	head, err := repo.Head()
1365→	if err != nil || !head.Name().IsBranch() {
1366→		return ""
1367→	}
1368→	return head.Name().Short()
1369→}
