1371→// getMainBranchHash returns the hash of the main branch (main or master).
1372→// Returns ZeroHash if no main branch is found.
1373→func GetMainBranchHash(repo *git.Repository) plumbing.Hash {
1374→	// Try common main branch names
1375→	for _, branchName := range []string{branchMain, branchMaster} {
1376→		// Try local branch first
1377→		ref, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
1378→		if err == nil {
1379→			return ref.Hash()
1380→		}
1381→		// Try remote tracking branch
1382→		ref, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
1383→		if err == nil {
1384→			return ref.Hash()
1385→		}
1386→	}
1387→	return plumbing.ZeroHash
1388→}
1389→
1390→// GetDefaultBranchName returns the name of the default branch.
1391→// First checks origin/HEAD, then falls back to checking if main/master exists.
1392→// Returns empty string if unable to determine.
1393→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
1394→func GetDefaultBranchName(repo *git.Repository) string {
1395→	// Try to get the symbolic reference for origin/HEAD
1396→	// Use resolved=false to get the symbolic ref itself, then extract its target
1397→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), false)
1398→	if err == nil && ref != nil && ref.Type() == plumbing.SymbolicReference {
1399→		target := ref.Target().String()
1400→		if branchName, found := strings.CutPrefix(target, "refs/remotes/origin/"); found {
1401→			return branchName
1402→		}
1403→	}
1404→
1405→	// Fallback: check if origin/main or origin/master exists
1406→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMain), true); err == nil {
1407→		return branchMain
1408→	}
1409→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMaster), true); err == nil {
1410→		return branchMaster
1411→	}
1412→
1413→	// Final fallback: check local branches
1414→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMain), true); err == nil {
1415→		return branchMain
1416→	}
1417→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMaster), true); err == nil {
1418→		return branchMaster
1419→	}
1420→
1421→	return ""
1422→}
1423→
1424→// IsOnDefaultBranch checks if the repository HEAD is on the default branch.
1425→// Returns (isOnDefault, currentBranchName).
1426→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
1427→func IsOnDefaultBranch(repo *git.Repository) (bool, string) {
1428→	currentBranch := GetCurrentBranchName(repo)
1429→	if currentBranch == "" {
1430→		return false, ""
1431→	}
1432→
1433→	defaultBranch := GetDefaultBranchName(repo)
1434→	if defaultBranch == "" {
1435→		// Can't determine default, check common names
1436→		if currentBranch == branchMain || currentBranch == branchMaster {
1437→			return true, currentBranch
1438→		}
1439→		return false, currentBranch
1440→	}
1441→
1442→	return currentBranch == defaultBranch, currentBranch
1443→}
