1445→// prepareTranscriptIfNeeded calls PrepareTranscript for agents that implement
1446→// the TranscriptPreparer interface. This ensures transcript files exist before
1447→// they are read (e.g., OpenCode creates its transcript lazily via `opencode export`).
1448→// Errors are silently ignored — this is best-effort for hook paths.
1449→func prepareTranscriptIfNeeded(agentType agent.AgentType, transcriptPath string) {
1450→	if transcriptPath == "" {
1451→		return
1452→	}
1453→	ag, err := agent.GetByAgentType(agentType)
1454→	if err != nil {
1455→		return
1456→	}
1457→	if preparer, ok := ag.(agent.TranscriptPreparer); ok {
1458→		// Best-effort: callers handle missing files gracefully.
1459→		// Transcript may not be available yet (e.g., agent not installed).
1460→		_ = preparer.PrepareTranscript(transcriptPath) //nolint:errcheck // Best-effort in hook path
1461→	}
1462→}
