 209→		entireDirAbs = paths.EntireDir // Fallback to relative
 210→	}
 211→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
 212→
 213→	if showNotification {
 214→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
 215→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
 216→	}
 217→
 218→	// Helper to save settings to the appropriate file
 219→	saveSettings := func() error {
 220→		if shouldUseLocal {
 221→			return SaveEntireSettingsLocal(settings)
 222→		}
 223→		return SaveEntireSettings(settings)
 224→	}
 225→
 226→	// Save settings before telemetry prompt so config is persisted even if the user cancels
 227→	if err := saveSettings(); err != nil {
 228→		return fmt.Errorf("failed to save settings: %w", err)
 229→	}
 230→
 231→	if _, err := strategy.InstallGitHook(true, localDev, absoluteHookPath); err != nil {
 232→		return fmt.Errorf("failed to install git hooks: %w", err)
 233→	}
 234→	strategy.CheckAndWarnHookManagers(w, localDev, absoluteHookPath)
 235→	fmt.Fprintln(w, "✓ Hooks installed")
 236→
 237→	configDisplay := configDisplayProject
 238→	if shouldUseLocal {
 239→		configDisplay = configDisplayLocal
 240→	}
 241→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
 242→
 243→	// Ask about telemetry consent (only if not already asked)
 244→	fmt.Fprintln(w)
 245→	if err := promptTelemetryConsent(settings, telemetry); err != nil {
 246→		return fmt.Errorf("telemetry consent: %w", err)
 247→	}
 248→	// Save again to persist telemetry choice
 249→	if err := saveSettings(); err != nil {
 250→		return fmt.Errorf("failed to save settings: %w", err)
 251→	}
 252→
 253→	if err := strategy.EnsureSetup(); err != nil {
 254→		return fmt.Errorf("failed to setup strategy: %w", err)
 255→	}
 256→
 257→	fmt.Fprintln(w, "\nReady.")
 258→
 259→	return nil
 260→}
