 576→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
 577→// If strategyName is provided, it sets the strategy; otherwise uses default.
 578→func setupAgentHooksNonInteractive(w io.Writer, ag agent.Agent, localDev, forceHooks, skipPushSessions, telemetry, absoluteHookPath bool) error {
 579→	agentName := ag.Name()
 580→	// Check if agent supports hooks
 581→	hookAgent, ok := ag.(agent.HookSupport)
 582→	if !ok {
 583→		return fmt.Errorf("agent %s does not support hooks", agentName)
 584→	}
 585→
 586→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
 587→
 588→	// Install agent hooks (agent hooks don't depend on settings)
 589→	installedHooks, err := hookAgent.InstallHooks(localDev, forceHooks)
 590→	if err != nil {
 591→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
 592→	}
 593→
 594→	// Setup .entire directory
 595→	if _, err := setupEntireDirectory(); err != nil {
 596→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 597→	}
 598→
 599→	// Load existing settings to preserve other options (like strategy_options.push)
 600→	settings, err := LoadEntireSettings()
 601→	if err != nil {
 602→		// If we can't load, start with defaults
 603→		settings = &EntireSettings{}
 604→	}
 605→	settings.Enabled = true
 606→	if localDev {
 607→		settings.LocalDev = localDev
 608→	}
 609→	if absoluteHookPath {
 610→		settings.AbsoluteHookPath = absoluteHookPath
 611→	}
 612→
 613→	// Set push_sessions option if --skip-push-sessions flag was provided
 614→	if skipPushSessions {
 615→		if settings.StrategyOptions == nil {
 616→			settings.StrategyOptions = make(map[string]interface{})
 617→		}
 618→		settings.StrategyOptions["push_sessions"] = false
 619→	}
 620→
 621→	// Handle telemetry for non-interactive mode
 622→	// Note: if telemetry is nil (not configured), it defaults to disabled
 623→	if !telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
 624→		f := false
 625→		settings.Telemetry = &f
 626→	}
 627→
 628→	if err := SaveEntireSettings(settings); err != nil {
 629→		return fmt.Errorf("failed to save settings: %w", err)
 630→	}
 631→
 632→	if _, err := strategy.InstallGitHook(true, localDev, absoluteHookPath); err != nil {
 633→		return fmt.Errorf("failed to install git hooks: %w", err)
 634→	}
 635→	strategy.CheckAndWarnHookManagers(w, localDev, absoluteHookPath)
 636→
 637→	if installedHooks == 0 {
 638→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
 639→		if ag.IsPreview() {
 640→			msg += " (Preview)"
 641→		}
 642→		fmt.Fprintf(w, "%s\n", msg)
 643→	} else {
 644→		msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
 645→		if ag.IsPreview() {
 646→			msg += " (Preview)"
 647→		}
 648→		fmt.Fprintf(w, "%s\n", msg)
 649→	}
 650→
 651→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
 652→
 653→	if err := strategy.EnsureSetup(); err != nil {
 654→		return fmt.Errorf("failed to setup strategy: %w", err)
 655→	}
 656→
 657→	fmt.Fprintln(w, "\nReady.")
 658→
 659→	return nil
 660→}
