 670→// determineSettingsTarget decides whether to write to settings.local.json based on:
 671→// - Whether settings.json already exists
 672→// - The --local and --project flags
 673→// Returns (useLocal, showNotification).
 674→func determineSettingsTarget(entireDir string, useLocal, useProject bool) (bool, bool) {
 675→	// Explicit --local flag always uses local settings
 676→	if useLocal {
 677→		return true, false
 678→	}
 679→
 680→	// Explicit --project flag always uses project settings
 681→	if useProject {
 682→		return false, false
 683→	}
 684→
 685→	// No flags specified - check if settings file exists
 686→	settingsPath := filepath.Join(entireDir, paths.SettingsFileName)
 687→	if _, err := os.Stat(settingsPath); err == nil {
 688→		// Settings file exists - auto-redirect to local with notification
 689→		return true, true
 690→	}
 691→
 692→	// Settings file doesn't exist - create it
 693→	return false, false
 694→}
