 696→// setupEntireDirectory creates the .entire directory and gitignore.
 697→// Returns true if the directory was created, false if it already existed.
 698→func setupEntireDirectory() (bool, error) { //nolint:unparam // already present in codebase
 699→	// Get absolute path for the .entire directory
 700→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
 701→	if err != nil {
 702→		entireDirAbs = paths.EntireDir // Fallback to relative
 703→	}
 704→
 705→	// Check if directory already exists
 706→	created := false
 707→	if _, err := os.Stat(entireDirAbs); os.IsNotExist(err) {
 708→		created = true
 709→	}
 710→
 711→	// Create .entire directory
 712→	//nolint:gosec // G301: Project directory needs standard permissions for git
 713→	if err := os.MkdirAll(entireDirAbs, 0o755); err != nil {
 714→		return false, fmt.Errorf("failed to create .entire directory: %w", err)
 715→	}
 716→
 717→	// Create/update .gitignore with all required entries
 718→	if err := strategy.EnsureEntireGitignore(); err != nil {
 719→		return false, fmt.Errorf("failed to setup .gitignore: %w", err)
 720→	}
 721→
 722→	return created, nil
 723→}
