 284→// ensureMetadataBranch creates the orphan entire/checkpoints/v1 branch if it doesn't exist.
 285→// This branch has no parent and starts with an empty tree.
 286→func EnsureMetadataBranch(repo *git.Repository) error {
 287→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
 288→
 289→	// Check if branch already exists
 290→	_, err := repo.Reference(refName, true)
 291→	if err == nil {
 292→		// Branch already exists
 293→		return nil
 294→	}
 295→
 296→	// Create empty tree (no files)
 297→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
 298→	obj := repo.Storer.NewEncodedObject()
 299→	if err := emptyTree.Encode(obj); err != nil {
 300→		return fmt.Errorf("failed to encode empty tree: %w", err)
 301→	}
 302→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
 303→	if err != nil {
 304→		return fmt.Errorf("failed to store empty tree: %w", err)
 305→	}
 306→
 307→	// Create orphan commit (no parent)
 308→	now := time.Now()
 309→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
 310→	sig := object.Signature{
 311→		Name:  authorName,
 312→		Email: authorEmail,
 313→		When:  now,
 314→	}
 315→
 316→	commit := &object.Commit{
 317→		TreeHash:  emptyTreeHash,
 318→		Author:    sig,
 319→		Committer: sig,
 320→		Message:   "Initialize metadata branch\n\nThis branch stores session metadata.\n",
 321→	}
 322→	// Note: No ParentHashes - this is an orphan commit
 323→
 324→	commitObj := repo.Storer.NewEncodedObject()
 325→	if err := commit.Encode(commitObj); err != nil {
 326→		return fmt.Errorf("failed to encode orphan commit: %w", err)
 327→	}
 328→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
 329→	if err != nil {
 330→		return fmt.Errorf("failed to store orphan commit: %w", err)
 331→	}
 332→
 333→	// Create branch reference
 334→	ref := plumbing.NewHashReference(refName, commitHash)
 335→	if err := repo.Storer.SetReference(ref); err != nil {
 336→		return fmt.Errorf("failed to create metadata branch: %w", err)
 337→	}
 338→
 339→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
 340→	return nil
 341→}
