 522→// ReadAllSessionPromptsFromTree reads the first prompt for all sessions in a multi-session checkpoint.
 523→// Returns a slice of prompts parallel to sessionIDs (oldest to newest).
 524→// For single-session checkpoints, returns a slice with just the root prompt.
 525→func ReadAllSessionPromptsFromTree(tree *object.Tree, checkpointPath string, sessionCount int, sessionIDs []string) []string {
 526→	if sessionCount <= 1 || len(sessionIDs) <= 1 {
 527→		// Single session - just return the root prompt
 528→		prompt := ReadSessionPromptFromTree(tree, checkpointPath)
 529→		if prompt != "" {
 530→			return []string{prompt}
 531→		}
 532→		return nil
 533→	}
 534→
 535→	// Multi-session: read prompts from archived folders (0/, 1/, etc.) and root
 536→	prompts := make([]string, len(sessionIDs))
 537→
 538→	// Read archived session prompts (folders 0, 1, ... N-2)
 539→	for i := range sessionCount - 1 {
 540→		archivedPath := fmt.Sprintf("%s/%d", checkpointPath, i)
 541→		prompts[i] = ReadSessionPromptFromTree(tree, archivedPath)
 542→	}
 543→
 544→	// Read the most recent session prompt (at root level)
 545→	prompts[len(prompts)-1] = ReadSessionPromptFromTree(tree, checkpointPath)
 546→
 547→	return prompts
 548→}
