 602→// IsInsideWorktree returns true if the current directory is inside a git worktree
 603→// (as opposed to the main repository). Worktrees have .git as a file pointing
 604→// to the main repo, while the main repo has .git as a directory.
 605→// This function works correctly from any subdirectory within the repository.
 606→func IsInsideWorktree() bool {
 607→	// First find the repository root
 608→	repoRoot, err := paths.WorktreeRoot()
 609→	if err != nil {
 610→		return false
 611→	}
 612→
 613→	gitPath := filepath.Join(repoRoot, gitDir)
 614→	gitInfo, err := os.Stat(gitPath)
 615→	if err != nil {
 616→		return false
 617→	}
 618→	return !gitInfo.IsDir()
 619→}
 620→
 621→// GetMainRepoRoot returns the root directory of the main repository.
 622→// In the main repo, this is the worktree path (repo root).
 623→// In a worktree, this parses the .git file to find the main repo.
 624→// This function works correctly from any subdirectory within the repository.
 625→//
 626→// Per gitrepository-layout(5), a worktree's .git file is a "gitfile" containing
 627→// "gitdir: <path>" pointing to $GIT_DIR/worktrees/<id> in the main repository.
 628→// See: https://git-scm.com/docs/gitrepository-layout
 629→func GetMainRepoRoot() (string, error) {
 630→	// First find the worktree/repo root
 631→	repoRoot, err := paths.WorktreeRoot()
 632→	if err != nil {
 633→		return "", fmt.Errorf("failed to get worktree path: %w", err)
 634→	}
 635→
 636→	if !IsInsideWorktree() {
 637→		return repoRoot, nil
 638→	}
 639→
 640→	// Worktree .git file contains: "gitdir: /path/to/main/.git/worktrees/<id>"
 641→	gitFilePath := filepath.Join(repoRoot, gitDir)
 642→	content, err := os.ReadFile(gitFilePath) //nolint:gosec // G304: gitFilePath is constructed from repo root, not user input
 643→	if err != nil {
 644→		return "", fmt.Errorf("failed to read .git file: %w", err)
 645→	}
 646→
 647→	gitdir := strings.TrimSpace(string(content))
 648→	gitdir = strings.TrimPrefix(gitdir, "gitdir: ")
 649→
 650→	// Extract main repo root: everything before "/.git/"
 651→	idx := strings.LastIndex(gitdir, "/.git/")
 652→	if idx < 0 {
 653→		return "", fmt.Errorf("unexpected gitdir format: %s", gitdir)
 654→	}
 655→	return gitdir[:idx], nil
 656→}
 657→
 658→// GetGitCommonDir returns the path to the shared git directory.
 659→// In a regular checkout, this is .git/
 660→// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
 661→// Uses git rev-parse --git-common-dir for reliable handling of worktrees.
 662→func GetGitCommonDir() (string, error) {
 663→	ctx := context.Background()
 664→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
 665→	cmd.Dir = "."
 666→	output, err := cmd.Output()
 667→	if err != nil {
 668→		return "", fmt.Errorf("failed to get git common dir: %w", err)
 669→	}
 670→
 671→	commonDir := strings.TrimSpace(string(output))
 672→
 673→	// git rev-parse --git-common-dir returns relative paths from the working directory,
 674→	// so we need to make it absolute if it isn't already
 675→	if !filepath.IsAbs(commonDir) {
 676→		commonDir = filepath.Join(".", commonDir)
 677→	}
 678→
 679→	return filepath.Clean(commonDir), nil
 680→}
