 682→// EnsureEntireGitignore ensures all required entries are in .entire/.gitignore
 683→// Works correctly from any subdirectory within the repository.
 684→func EnsureEntireGitignore() error {
 685→	// Get absolute path for the gitignore file
 686→	gitignoreAbs, err := paths.AbsPath(entireGitignore)
 687→	if err != nil {
 688→		gitignoreAbs = entireGitignore // Fallback to relative
 689→	}
 690→
 691→	// Read existing content
 692→	var content string
 693→	if data, err := os.ReadFile(gitignoreAbs); err == nil { //nolint:gosec // path is from AbsPath or constant
 694→		content = string(data)
 695→	}
 696→
 697→	// All entries that should be in .entire/.gitignore
 698→	requiredEntries := []string{
 699→		"tmp/",
 700→		"settings.local.json",
 701→		"metadata/",
 702→		"logs/",
 703→	}
 704→
 705→	// Track what needs to be added
 706→	var toAdd []string
 707→	for _, entry := range requiredEntries {
 708→		if !strings.Contains(content, entry) {
 709→			toAdd = append(toAdd, entry)
 710→		}
 711→	}
 712→
 713→	// Nothing to add
 714→	if len(toAdd) == 0 {
 715→		return nil
 716→	}
 717→
 718→	// Ensure .entire directory exists
 719→	if err := os.MkdirAll(filepath.Dir(gitignoreAbs), 0o750); err != nil {
 720→		return fmt.Errorf("failed to create .entire directory: %w", err)
 721→	}
 722→
 723→	// Append missing entries to gitignore
 724→	var sb strings.Builder
 725→	for _, entry := range toAdd {
 726→		sb.WriteString(entry + "\n")
 727→	}
 728→	content += sb.String()
 729→
 730→	if err := os.WriteFile(gitignoreAbs, []byte(content), 0o644); err != nil { //nolint:gosec // path is from AbsPath or constant
 731→		return fmt.Errorf("failed to write gitignore: %w", err)
 732→	}
 733→	return nil
 734→}
