 736→// checkCanRewindWithWarning checks working directory and returns a warning with diff stats.
 737→// Always returns canRewind=true but includes a warning message with +/- line stats for
 738→// uncommitted changes. Used by manual-commit strategy.
 739→func checkCanRewindWithWarning() (bool, string, error) {
 740→	repo, err := OpenRepository()
 741→	if err != nil {
 742→		// Can't open repo - still allow rewind but without stats
 743→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo can't be opened
 744→	}
 745→
 746→	worktree, err := repo.Worktree()
 747→	if err != nil {
 748→		return true, "", nil //nolint:nilerr // Rewind allowed even if worktree can't be accessed
 749→	}
 750→
 751→	status, err := worktree.Status()
 752→	if err != nil {
 753→		return true, "", nil //nolint:nilerr // Rewind allowed even if status can't be retrieved
 754→	}
 755→
 756→	if status.IsClean() {
 757→		return true, "", nil
 758→	}
 759→
 760→	// Get HEAD commit tree for comparison - if we can't get it, just return without stats
 761→	head, err := repo.Head()
 762→	if err != nil {
 763→		return true, "", nil //nolint:nilerr // Rewind allowed even without HEAD (e.g., empty repo)
 764→	}
 765→
 766→	headCommit, err := repo.CommitObject(head.Hash())
 767→	if err != nil {
 768→		return true, "", nil //nolint:nilerr // Rewind allowed even if commit lookup fails
 769→	}
 770→
 771→	headTree, err := headCommit.Tree()
 772→	if err != nil {
 773→		return true, "", nil //nolint:nilerr // Rewind allowed even if tree lookup fails
 774→	}
 775→
 776→	type fileChange struct {
 777→		status   string // "modified", "added", "deleted"
 778→		added    int
 779→		removed  int
 780→		filename string
 781→	}
 782→
 783→	var changes []fileChange
 784→	// Use repo root, not cwd - git status returns paths relative to repo root
 785→	repoRoot, err := paths.WorktreeRoot()
 786→	if err != nil {
 787→		return true, "", nil //nolint:nilerr // Rewind allowed even if worktree root lookup fails
 788→	}
 789→
 790→	for file, st := range status {
 791→		// Skip .entire directory
 792→		if paths.IsInfrastructurePath(file) {
 793→			continue
 794→		}
 795→
 796→		// Skip untracked files
 797→		if st.Worktree == git.Untracked {
 798→			continue
 799→		}
 800→
 801→		var change fileChange
 802→		change.filename = file
 803→
 804→		switch {
 805→		case st.Staging == git.Added || st.Worktree == git.Added:
 806→			change.status = "added"
 807→			// New file - count all lines as added
 808→			absPath := filepath.Join(repoRoot, file)
 809→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
 810→				change.added = countLines(content)
 811→			}
 812→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
 813→			change.status = "deleted"
 814→			// Deleted file - count lines from HEAD as removed
 815→			if entry, err := headTree.File(file); err == nil {
 816→				if content, err := entry.Contents(); err == nil {
 817→					change.removed = countLines([]byte(content))
 818→				}
 819→			}
 820→		case st.Staging == git.Modified || st.Worktree == git.Modified:
 821→			change.status = "modified"
 822→			// Modified file - compute diff stats
 823→			var headContent, workContent []byte
 824→			if entry, err := headTree.File(file); err == nil {
 825→				if content, err := entry.Contents(); err == nil {
 826→					headContent = []byte(content)
 827→				}
 828→			}
 829→			absPath := filepath.Join(repoRoot, file)
 830→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
 831→				workContent = content
 832→			}
 833→			if headContent != nil && workContent != nil {
 834→				change.added, change.removed = computeDiffStats(headContent, workContent)
 835→			}
 836→		default:
 837→			continue
 838→		}
 839→
 840→		changes = append(changes, change)
 841→	}
 842→
 843→	if len(changes) == 0 {
 844→		return true, "", nil
 845→	}
 846→
 847→	// Sort changes by filename for consistent output
 848→	sort.Slice(changes, func(i, j int) bool {
 849→		return changes[i].filename < changes[j].filename
 850→	})
 851→
 852→	var msg strings.Builder
 853→	msg.WriteString("The following uncommitted changes will be reverted:\n")
 854→
 855→	totalAdded, totalRemoved := 0, 0
 856→	for _, c := range changes {
 857→		totalAdded += c.added
 858→		totalRemoved += c.removed
 859→
 860→		var stats string
 861→		switch {
 862→		case c.added > 0 && c.removed > 0:
 863→			stats = fmt.Sprintf("+%d/-%d", c.added, c.removed)
 864→		case c.added > 0:
 865→			stats = fmt.Sprintf("+%d", c.added)
 866→		case c.removed > 0:
 867→			stats = fmt.Sprintf("-%d", c.removed)
 868→		}
 869→
 870→		msg.WriteString(fmt.Sprintf("  %-10s %s", c.status+":", c.filename))
 871→		if stats != "" {
 872→			msg.WriteString(fmt.Sprintf(" (%s)", stats))
 873→		}
 874→		msg.WriteString("\n")
 875→	}
 876→
 877→	if totalAdded > 0 || totalRemoved > 0 {
 878→		msg.WriteString(fmt.Sprintf("\nTotal: +%d/-%d lines\n", totalAdded, totalRemoved))
 879→	}
 880→
 881→	return true, msg.String(), nil
 882→}
