 948→// StageFilesContext describes what type of staging operation this is (for messages).
 949→type StageFilesContext string
 950→
 951→const (
 952→	// StageForSession is used when staging files for a session checkpoint.
 953→	StageForSession StageFilesContext = "session"
 954→	// StageForTask is used when staging files for a task checkpoint.
 955→	StageForTask StageFilesContext = "task"
 956→)
 957→
 958→// StageFiles stages modified, new, and deleted files to the git worktree.
 959→//
 960→// This function handles three categories of file changes:
 961→//  1. Modified files: existing files that have been changed
 962→//  2. New files: files that were created during the session
 963→//  3. Deleted files: files that were removed during the session
 964→//
 965→// Error Handling Strategy:
 966→//   - Individual file staging errors are logged to stderr but don't fail the operation
 967→//   - This ensures that partial staging succeeds even if some files have issues
 968→//   - If a modified file no longer exists, it's treated as a deletion
 969→//
 970→// The stageCtx parameter is used for user-facing messages to indicate whether
 971→// this is staging for a session checkpoint or a task checkpoint.
 972→func StageFiles(worktree *git.Worktree, modified, newFiles, deleted []string, stageCtx StageFilesContext) {
 973→	// Get worktree root for resolving file paths
 974→	// This is critical because fileExists() uses os.Stat() which resolves relative to CWD,
 975→	// but worktree.Add/Remove resolve relative to repo root. If CWD != repo root,
 976→	// fileExists() could return false for existing files, causing worktree.Remove()
 977→	// to incorrectly delete them.
 978→	repoRoot := worktree.Filesystem.Root()
 979→
 980→	// Stage modified files
 981→	for _, file := range modified {
 982→		// Resolve path relative to repo root for existence check
 983→		absPath := filepath.Join(repoRoot, file)
 984→		if fileExists(absPath) {
 985→			if _, err := worktree.Add(file); err != nil {
 986→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
 987→			} else {
 988→				fmt.Fprintf(os.Stderr, "  Staged: %s\n", file)
 989→			}
 990→		} else {
 991→			// File was deleted - stage the deletion
 992→			if _, err := worktree.Remove(file); err != nil {
 993→				fmt.Fprintf(os.Stderr, "  File not found or deleted: %s\n", file)
 994→			}
 995→		}
 996→	}
 997→
 998→	// Stage new files
 999→	if len(newFiles) > 0 {
1000→		fmt.Fprintf(os.Stderr, "Staging %d new files created during %s:\n", len(newFiles), stageCtx)
1001→		for _, file := range newFiles {
1002→			if _, err := worktree.Add(file); err != nil {
1003→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
1004→			} else {
1005→				fmt.Fprintf(os.Stderr, "  Staged new file: %s\n", file)
1006→			}
1007→		}
1008→	}
1009→
1010→	// Stage deleted files
1011→	for _, file := range deleted {
1012→		if _, err := worktree.Remove(file); err != nil {
1013→			fmt.Fprintf(os.Stderr, "  Failed to stage deleted file %s: %v\n", file, err)
1014→		} else {
1015→			fmt.Fprintf(os.Stderr, "  Staged deleted file: %s\n", file)
1016→		}
1017→	}
1018→}
