1020→// getTaskCheckpointFromTree retrieves a task checkpoint from a commit tree.
1021→// Shared implementation for shadow and linear-shadow strategies.
1022→func getTaskCheckpointFromTree(point RewindPoint) (*TaskCheckpoint, error) {
1023→	if !point.IsTaskCheckpoint {
1024→		return nil, ErrNotTaskCheckpoint
1025→	}
1026→
1027→	repo, err := OpenRepository()
1028→	if err != nil {
1029→		return nil, fmt.Errorf("failed to open repository: %w", err)
1030→	}
1031→
1032→	commitHash := plumbing.NewHash(point.ID)
1033→	commit, err := repo.CommitObject(commitHash)
1034→	if err != nil {
1035→		return nil, fmt.Errorf("failed to get commit: %w", err)
1036→	}
1037→
1038→	tree, err := commit.Tree()
1039→	if err != nil {
1040→		return nil, fmt.Errorf("failed to get tree: %w", err)
1041→	}
1042→
1043→	// Read checkpoint.json from the tree
1044→	checkpointPath := point.MetadataDir + "/checkpoint.json"
1045→	file, err := tree.File(checkpointPath)
1046→	if err != nil {
1047→		return nil, fmt.Errorf("failed to find checkpoint at %s: %w", checkpointPath, err)
1048→	}
1049→
1050→	content, err := file.Contents()
1051→	if err != nil {
1052→		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
1053→	}
1054→
1055→	var checkpoint TaskCheckpoint
1056→	if err := json.Unmarshal([]byte(content), &checkpoint); err != nil {
