1274→// getSessionDescriptionFromTree reads the first line of prompt.txt or context.md from a git tree.
1275→// This is the tree-based equivalent of getSessionDescription (which reads from filesystem).
1276→//
1277→// If metadataDir is provided, looks for files at metadataDir/prompt.txt or metadataDir/context.md.
1278→// If metadataDir is empty, first tries the root of the tree (for when the tree is already
1279→// the session directory), then falls back to
1280→// searching for .entire/metadata/*/prompt.txt or context.md (for full worktree trees).
1281→func getSessionDescriptionFromTree(tree *object.Tree, metadataDir string) string {
1282→	// Helper to read first line from a file in tree
1283→	readFirstLine := func(path string) string {
1284→		file, err := tree.File(path)
1285→		if err != nil {
1286→			return ""
1287→		}
1288→		content, err := file.Contents()
1289→		if err != nil {
1290→			return ""
1291→		}
1292→		lines := strings.SplitN(content, "\n", 2)
1293→		if len(lines) > 0 && lines[0] != "" {
1294→			desc := strings.TrimSpace(lines[0])
1295→			// Remove markdown header prefix if present
1296→			return strings.TrimPrefix(desc, "# ")
1297→		}
1298→		return ""
1299→	}
1300→
1301→	// If metadataDir is provided, look there directly
1302→	if metadataDir != "" {
1303→		if desc := readFirstLine(metadataDir + "/" + paths.PromptFileName); desc != "" {
1304→			return desc
1305→		}
1306→		if desc := readFirstLine(metadataDir + "/" + paths.ContextFileName); desc != "" {
1307→			return desc
1308→		}
1309→		return NoDescription
1310→	}
1311→
1312→	// No metadataDir provided - first try looking at the root of the tree
1313→	// (used when the tree is already the session directory)
1314→	if desc := readFirstLine(paths.PromptFileName); desc != "" {
1315→		return desc
1316→	}
1317→	if desc := readFirstLine(paths.ContextFileName); desc != "" {
1318→		return desc
1319→	}
1320→
1321→	// Fall back to searching for .entire/metadata/*/prompt.txt or context.md
1322→	// (used when the tree is the full worktree)
1323→	var desc string
1324→	//nolint:errcheck // We ignore errors here as we're just searching for a description
1325→	_ = tree.Files().ForEach(func(f *object.File) error {
1326→		if desc != "" {
1327→			return nil // Already found description
1328→		}
1329→		name := f.Name
1330→		if strings.Contains(name, ".entire/metadata/") {
1331→			if strings.HasSuffix(name, "/"+paths.PromptFileName) || strings.HasSuffix(name, "/"+paths.ContextFileName) {
1332→				content, err := f.Contents()
1333→				if err != nil {
1334→					return nil //nolint:nilerr // Skip files we can't read, continue searching
1335→				}
1336→				lines := strings.SplitN(content, "\n", 2)
1337→				if len(lines) > 0 && lines[0] != "" {
1338→					desc = strings.TrimSpace(lines[0])
1339→					desc = strings.TrimPrefix(desc, "# ")
1340→				}
1341→			}
1342→		}
1343→		return nil
1344→	})
1345→
1346→	if desc != "" {
1347→		return desc
1348→	}
1349→	return NoDescription
1350→}
